{"script": "python3 << 'EOF'
import FreeCAD

# Open the precondition file
doc = FreeCAD.open("/home/user/Precondition_Unnamed.FCStd")

# Get the sketch
sketch = doc.getObject("Sketch")
print(f"Sketch: {sketch.Name}")
print(f"TypeId: {sketch.TypeId}")

# Check attachment
if hasattr(sketch, 'MapMode'):
    print(f"MapMode: {sketch.MapMode}")
if hasattr(sketch, 'AttachmentOffset'):
    print(f"AttachmentOffset: {sketch.AttachmentOffset}")

# Get sketch geometry
if hasattr(sketch, 'Geometry'):
    print(f"\nNumber of geometry elements: {len(sketch.Geometry)}")
    for i, geom in enumerate(sketch.Geometry):
        print(f"  Geometry {i}: Type={geom.Type}")
        if hasattr(geom, 'Placement'):
            print(f"    Placement: {geom.Placement}")
        # For lines
        if hasattr(geom, 'StartPoint') and hasattr(geom, 'EndPoint'):
            print(f"    StartPoint: {geom.StartPoint}")
            print(f"    EndPoint: {geom.EndPoint}")
        if hasattr(geom, 'Radius'):
            print(f"    Radius: {geom.Radius}")

# Get constraints
if hasattr(sketch, 'Constraints'):
    print(f"\nNumber of constraints: {len(sketch.Constraints)}")
    for i, c in enumerate(sketch.Constraints):
        print(f"  Constraint {i}: {c}")

FreeCAD.closeDocument(doc.Name)
EOF"}
